"""Fingerprints of decoded audio. Recordings are tones generated by FFmpeg during the test."""

from pathlib import Path

from app.audio import duplicates, ffmpeg
from tests.audio_fixtures import make_audio, requires_ffmpeg

VERSION = "ffmpeg version 6.1.1-3ubuntu5"


def fingerprint(tmp_path: Path, container: str, tone: str, version: str = VERSION) -> str:
    source, pcm = tmp_path / f"{container}-{tone}", tmp_path / f"{container}-{tone}.pcm"
    make_audio(source, container, source=f"sine=frequency={tone}:duration=2")
    ffmpeg.convert(source, container, duplicates.PCM_ARGS, pcm, timeout=60)
    return duplicates.pcm_sha256(pcm, version)


def test_the_decoder_version_is_part_of_the_fingerprint(tmp_path: Path) -> None:
    pcm = tmp_path / "pcm"
    pcm.write_bytes(b"\x00\x01" * 100)
    assert duplicates.pcm_sha256(pcm, VERSION) == duplicates.pcm_sha256(pcm, VERSION)
    assert duplicates.pcm_sha256(pcm, VERSION) != duplicates.pcm_sha256(pcm, "ffmpeg version 7")


@requires_ffmpeg
def test_the_same_sound_in_another_lossless_format_matches(tmp_path: Path) -> None:
    assert fingerprint(tmp_path, "wav", "220") == fingerprint(tmp_path, "flac", "220")


@requires_ffmpeg
def test_a_different_sound_does_not_match(tmp_path: Path) -> None:
    assert fingerprint(tmp_path, "wav", "220") != fingerprint(tmp_path, "wav", "330")
